      if (!containerRef) return;
      cards = Array.from(containerRef.children) as HTMLElement[];
      total = cards.length;
      cards.forEach((card, i) => {
        const stickyTop = reverseScale() && i === total - 1 ? topStart() : topStart() + i * topIncrement();
